/**
 * npm run build:widgets
 *
 * Builds every widget in widgets/ into a single HTML file (vite.widgets.config.ts), then
 * writes src/widgets/generated.ts, which exports each one as a string. The Worker imports
 * that file and serves each widget as a ui:// resource. The generated file is build
 * output: git ignores it, and `npm test`, `npm run dev` and `npm run deploy` rebuild it first.
 */
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { build } from "vite";

const root = join(import.meta.dirname, "..");
const names = readdirSync(join(root, "widgets"), { withFileTypes: true })
  .filter((d) => d.isDirectory() && d.name !== "shared")
  .map((d) => d.name)
  .sort();

const out: Record<string, string> = {};
for (const name of names) {
  process.env.WIDGET = name;
  await build({ configFile: join(root, "vite.widgets.config.ts") });
  out[name] = readFileSync(join(root, "dist", "widgets", name, "index.html"), "utf8");
  console.log(`  ${name}: ${(out[name].length / 1024).toFixed(0)} KB`);
}

writeFileSync(
  join(root, "src", "widgets", "generated.ts"),
  "// GENERATED by scripts/build-widgets.ts. Do not edit; run npm run build:widgets.\n" +
    `export const WIDGET_HTML = ${JSON.stringify(out)} as const;\n`,
);
console.log(`Wrote src/widgets/generated.ts (${names.length} widgets).`);
